from __future__ import unicode_literals
from builtins import str
from future.utils import python_2_unicode_compatible
from collections import OrderedDict
from .exceptions import WtsConfigError
import re
import logging
import io

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


@python_2_unicode_compatible
class Command(object):

    def __init__(self, command_string):
        self.command_string = command_string
        self.parts = sorted(command_string.split("_"))

    def __eq__(self, other):
        return self.parts == other.parts

    def __ne__(self, other):
        return self.parts != other.parts

    def __str__(self):
        return self.command_string


@python_2_unicode_compatible
class CommandLine(object):

    def __init__(self, line):
        re_command_line = r"^(\w+)(?:\s+(?:(\w+)=)?(\S+))*$"
        assert re.search(re_command_line, line), (
            "command line '{command_line}' does not match '{re_command_line}'".format(
                command_line=line,
                re_command_line=re_command_line))

        re_params = re.compile(r' (?:(\w+)=)?("?)(\S+)\2')
        self.command = Command(
            command_string=re.match(r'(\w+)', line).group(1))
        self.params = self.store_parameters_dict(line, re_params)

    def __str__(self):
        params_str = self.restore_params(self.params)
        return "{command}{params}".format(
            command=str(self.command),
            params=params_str)

    def __eq__(self, other):
        return self.command == other.command and self.params == other.params

    def __ne__(self, other):
        return self.command != other.command or self.params != other.params

    @staticmethod
    def store_parameters_dict(line, reg_ex):
        dictionary = OrderedDict()
        for key, quote, value in reg_ex.findall(line):
            dictionary.setdefault(key, []).append(value)
        return dictionary

    def restore_params(self, dictionary):
        params_string = ""
        for k, v in dictionary.items():
            key = k + "=" if k else k
            for value in v:
                params_string += " {key}{value}".format(
                    key=key,
                    value='"{}"'.format(value) if str(self.command) == "set" else value)
        return params_string

    def match(self, partial):
        if self.command != partial.command:
            return False
        return (set((k, vv) for k, v in partial.params.items() for vv in v)
                <= set((k, vv) for k, v in self.params.items() for vv in v))

    def apply(self, modification):
        re_mod = re.compile(r'(?:(\w+)=)?("?)(\S+)\2')
        new_params_dict = self.store_parameters_dict(modification, re_mod)
        self.params.update(new_params_dict)

    def clone(self):
        return CommandLine(line=str(self))


@python_2_unicode_compatible
class WTSOperations(object):
    """
    This class encapsulates wts config object,
    it contains all configuration from file.
    """

    def __init__(self):
        self._config_original = []
        self._cmd_list = []

    def load_wts_cfg(self, file_name):
        self.__init__()
        # to be refactored by using generator pattern
        with io.open(file_name, 'r') as config:
            self._config_original = self._remove_comments_and_empty_lines(config.readlines())
        self._process_config_contents()

    def _process_config_contents(self):
        for line in self._config_original:
            cmd_line = CommandLine(line)
            self._cmd_list.append(cmd_line)

    def __str__(self):
        current_cfg = ''
        for cmd in self._cmd_list:
            current_cfg += str(cmd) + '\n'
        return current_cfg

    @staticmethod
    def _remove_comments_and_empty_lines(lines):
        # to be refactored by using generator pattern
        return filter(
            None,
            [line.split("#")[0].strip() for line in lines])

    def save_wts_cfg(self, file_path, encoding='UTF-8'):
        with io.open(file_path, 'w', encoding=encoding) as config:
            for cmd in self._cmd_list:
                config.write(str(cmd) + '\n')

    @staticmethod
    def _validate_location(location):
        if location.upper() not in ['AFTER', 'BEFORE']:
            raise WtsConfigError("Location: '%s' not valid" % location)

    @staticmethod
    def _prepare_commands_for_insert(command, location):
        if isinstance(command, str):
            command = [command]
        else:
            assert isinstance(command, list), (
                "command {command!r} has to be text or list, not {command_type}".format(
                    command=command,
                    command_type=type(command)))
        if location.upper() == "AFTER":
            command = reversed(command)
        return command

    def insert(self, command, location, reference):
        self._validate_location(location)
        reference_found = False
        cmd_reference = CommandLine(reference)
        command_list = self._prepare_commands_for_insert(command, location)
        for each_command in command_list:
            for cmd in self._cmd_list:
                if cmd.match(cmd_reference):
                    index = self._cmd_list.index(cmd)
                    if location.upper() == "AFTER":
                        index += 1
                    new_command = CommandLine(each_command)
                    self._cmd_list.insert(index, new_command)
                    reference_found = True
                    break
        if not reference_found:
            raise WtsConfigError("reference: '%s' not found" % reference)

    def modify(self, command, modification):
        cmd_to_modify_ref = CommandLine(command)
        for cmd in self._cmd_list:
            if cmd.match(cmd_to_modify_ref):
                cmd.apply(modification)
                return
        raise WtsConfigError("command: '%s' not found" % command)

    def delete(self, command):
        cmd_to_delete_ref = CommandLine(command)
        for cmd in list(self._cmd_list):
            if cmd.match(cmd_to_delete_ref):
                logger.info('deleting: ' + str(cmd))
                index = self._cmd_list.index(cmd)
                self._cmd_list.pop(index)

    def get(self, command):
        cmd_to_get_ref = CommandLine(command)
        for cmd in self._cmd_list:
            if cmd.match(cmd_to_get_ref):
                return str(cmd)
        logger.info("command: '%s' not found" % command)
        return None

    def find_all(self, command):
        partial_command_line = CommandLine(command)
        found_commands = []

        for command_line in self._cmd_list:
            if command_line.match(partial_command_line):
                found_commands.append(str(command_line))

        return found_commands

    def find_all_by_parameter(self, parameter, parameter_filter):
        found_commands = []
        for command_line in self._cmd_list:
            partial_command_line = CommandLine(self._add_command_parameter(command_line.command, parameter_filter))
            if command_line.match(partial_command_line) and parameter in command_line.params.keys():
                found_commands.append(str(command_line))

        return found_commands

    @staticmethod
    def _add_command_parameter(command, parameter):
        extended_command = str(command)
        if parameter is not None and len(str(parameter)) > 0:
            extended_command = "{} {}".format(command, parameter)
        return extended_command

    def clone_and_modify(self, base_command, modification, location=None, reference=None):
        if reference is None:
            reference = base_command
        if location is None:
            location = 'after'
        base_cmd_to_modify = CommandLine(base_command)
        for cmd in self._cmd_list:
            if cmd.match(base_cmd_to_modify):
                new_cmd = cmd.clone()
                new_cmd.apply(modification)
                self.insert(str(new_cmd), location, reference)
                return
        raise WtsConfigError("base command: '%s' not found" % base_command)

    def get_parameter(self, command, parameter):
        parameter_list = self.get_parameter_as_list(command, parameter)
        return WTSOperations.convert_list_of_strings_to_comma_separated_string(parameter_list)

    def get_parameter_as_list(self, command, parameter):
        command_line = CommandLine(command)
        for cmd in self._cmd_list:
            if cmd.match(command_line) and parameter in cmd.params.keys():
                return cmd.params[parameter]
        else:
            return []

    @staticmethod
    def convert_comma_separated_string_to_list(comma_separated_string):
        return list(map(str.strip, comma_separated_string.split(","))) if comma_separated_string else []

    @staticmethod
    def convert_list_of_strings_to_comma_separated_string(list_of_strings):
        return ", ".join(value for value in list_of_strings)

    @staticmethod
    def get_parameter_from_command_line_as_list(command, parameter):
        command_line = CommandLine(command)
        return command_line.params.get(parameter, [])
